INSERT INTO "stimuli" ("id", "subject_id", "source_document_id", "title", "content_text", "media_type", "media_path", "instructions", "created_at", "source_page", "visual_transcription", "visual_description") VALUES ('5307caf0-1c46-452e-a152-15a3399ee169', 1, 'f59ac90b-509a-493d-a75b-ae85c4c0cadf', 'JOHNNY', '«Conozco a un tipo»: Esta es la frase recurrente que define a Johnny. A secas. Johnny era así, uno le decía: me encantaría multiplicar mis ahorros por mil. Y él: "Conozco a un tipo". Me encantaría viajar a Cuba, comprar unos habanos y volver. ¿Para qué? Para venderlo. "Conozco a un tipo". Me encantaría hacerme un tatuaje. ¿Dónde? En la nuca: "Conozco a un tipo". Me encantaría quedarme acá para siempre. Y ahí Johnny ya no conocía a nadie. Decía: este es un país muy duro. Pero él vivía como un magnate, cambiaba de carro cada seis meses y seguía pagando el mismo leasing; cobraba un subsidio de desempleo que nadie le controlaba y era con eso que pagaba los moteles donde tirábamos, o las langostas que nos comíamos en Key West, o los VIP passes de los bares de salsa a los que le gustaba llevarme en Calle Ocho. Johnny vivía a expensas de su mujer –mitad gringa, mitad ecuatoriana– y compraba hasta los calzoncillos de marca: alimentaba rigurosamente su pequeño sueño americano como si temiera que, si un día se olvidaba de hacerlo, se desplomara a sus pies como un pajarito famélico.', 'none', NULL, 'RESPONDE LAS PREGUNTAS 1 A 3 DE ACUERDO CON LA SIGUIENTE INFORMACIÓN', '2026-11-10 13:37:26+00', 6, NULL, NULL);
INSERT INTO "stimuli" ("id", "subject_id", "source_document_id", "title", "content_text", "media_type", "media_path", "instructions", "created_at", "source_page", "visual_transcription", "visual_description") VALUES ('15155459-db8a-4d27-bf74-224dcf08ca9e', 1, 'f59ac90b-509a-493d-a75b-ae85c4c0cadf', 'Instinto en lugar de lógica', 'Cuando llega la hora de poner sus huevos, la avispa Sphex construye una pequeña madriguera para este propósito y sale en la búsqueda de un grillo al cual pica de manera tal que lo paraliza, pero no lo mata. La avispa lleva al grillo a su madriguera, deja sus huevos, cierra la madriguera y luego se va para no volver. Pasado un tiempo, los huevos crecen y la cría de la avispa se alimenta del grillo paralizado que no se descompone debido a que ha permanecido congelado. Para la mente humana, tal rutina tan organizada y aparentemente llena de propósitos lleva consigo un sabor de lógica y de pensamiento. O por lo menos esto es así hasta que conocemos más detalles. Por ejemplo, la rutina de la avispa consiste en llevar al grillo hacia la madriguera, dejarlo en la entrada, ir adentro a revisar que todo esté bien, salir y luego dejar el grillo adentro. Si, mientras la avispa está dentro de la madriguera haciendo su inspección preliminar, el grillo es movido algunos centímetros de la entrada, entonces la avispa, al salir de la madriguera, volverá a dejar al grillo de nuevo en la entrada, pero no adentro, y repetirá el procedimiento preparatorio de entrar a la madriguera a revisar que todo esté bien. Si, de nuevo, el grillo es movido unos centímetros de la entrada, la avispa llevará otra vez al grillo hacia la entrada y volverá a entrar a la madriguera para revisarla. La avispa nunca piensa en llevar al grillo directamente a su madriguera. En una ocasión, este procedimiento fue repetido cuarenta veces, siempre con el mismo resultado.', 'none', NULL, 'RESPONDE LAS PREGUNTAS 4 Y 5 DE ACUERDO CON LA SIGUIENTE INFORMACIÓN', '2026-11-10 13:37:26+00', 8, NULL, NULL);
INSERT INTO "stimuli" ("id", "subject_id", "source_document_id", "title", "content_text", "media_type", "media_path", "instructions", "created_at", "source_page", "visual_transcription", "visual_description") VALUES ('77fc7d36-3040-4ffb-8bcb-2c42deea8278', 1, 'f59ac90b-509a-493d-a75b-ae85c4c0cadf', 'Es noche de martes', 'Diego lava lechuga. Yo corto cebollas, pico tomates, controlo una salsa. Abrimos un vino. Después de comer, cruza sus cubiertos y me dice que qué bien cocino. Que soy rebuena ama de casa. Ahora –mucha confianza y años juntos– sólo finjo que me enojo y él, que me conoce, finge que se sorprende con mi ceño fruncido. Sabe que me gusta cocinar y tener la casa ordenada, pero sabe, también, que imagino el infierno bajo la forma de las tareas del hogar como ocupación obligatoria y excluyente. Tenemos cuentas separadas, casa compartida y responsabilidades iguales. En fin: casi. Porque si bien no hay nada que sea tarea exclusiva de Diego, sacar la ropa del tendedero y guardarla en los placares es una de esas cosas que “si-no-las-hago-yo-no-las-hace-nadie”. A Diego, simplemente, no le importa ver la ropa colgada durante meses, y yo prefiero que las medias y los calzones no me arruinen la vista del balcón, de modo que una vez por semana me transformo en mi mamá, que volvía del fondo con una parva de sábanas oliendo a sol, y junto la ropa recién lavada. Cada tanto me canso y revoleo mi derecho a la igualdad, entonces Diego dice con ternura “Sí, gordita, tenés razón”, dobla un par de remeras y a la semana otra vez: ahí voy yo, juntando broches. También soy la encargada de la sección “comidas difíciles” (Diego es del Club del Bifecito a la Plancha, si le toca cocinar). Si llego tarde a casa, sobre el pálido desierto de la mesa lucirá, con suerte, el laguito rojo de un tomate cortado al medio. Si es Diego el que llega tarde, de guacamole para arriba habrá de todo. Antes pensaba que estas cosas –el orden, la comida caliente, una casa agradable– tenían que ver con cierta sensibilidad femenina en la que, por cierto, me cuesta creer: tengo amigos varones que viven solos y sus casas son tan agradables como la mía y cocinan mejor que yo. Prefiero pensar que son síntomas –visibles– de mi educación de buen partido: prolija, limpia, ordenada. Cosas que aprendí de mi madre: perfumar la casa con cascarita de naranja, sacar las frazadas al sol.', 'none', NULL, 'RESPONDE LAS PREGUNTAS 9 Y 10 DE ACUERDO CON LA SIGUIENTE INFORMACIÓN', '2026-11-10 13:37:27+00', 11, NULL, NULL);
INSERT INTO "stimuli" ("id", "subject_id", "source_document_id", "title", "content_text", "media_type", "media_path", "instructions", "created_at", "source_page", "visual_transcription", "visual_description") VALUES ('55081719-b1cd-440b-9487-33f42f66f5a8', 1, 'f59ac90b-509a-493d-a75b-ae85c4c0cadf', 'Máxima emergencia', 'Infografía sobre pasos de reanimación cardiopulmonar.', 'none', NULL, 'RESPONDE LAS PREGUNTAS 6 A 8 DE ACUERDO CON EL SIGUIENTE CONTEXTO', '2026-11-10 13:37:27+00', 9, 'Máxima emergencia. LLAMAR A EMERGENCIAS: Informar el lugar del accidente, el número de víctimas, qué les pasó y los síntomas. 107 Capital Federal, 911/107 Provincia. POSICIONAR A LA VÍCTIMA: Si está boca abajo, girarla boca arriba. CHEQUEAR SI RESPIRA: Elevar el mentón con una mano. Acercar el oído a la boca de la víctima, mirar el pecho, escuchar y sentir si respira. SI RESPIRA PASAR AL PASO 5. SI NO RESPIRA HACER RESPIRACIÓN BOCA A BOCA: Con una mano tapar la nariz y extender la cabeza. Con la otra elevar el mentón. Sellar una boca con otra y soplar. Soplar durante dos segundos y dejar salir el aire. Repetir la maniobra dos veces. REANIMACIÓN CARDÍACA: SI NO TIENE PULSO. Buscar el eje del esternón, colocar el talón de la mano sobre el tórax, dos dedos por encima de la unión de las costillas. Apoyar la otra mano encima. Comprimir el tórax entre 4 y 5 cm en forma rítmica 15 veces. SI NO RESPIRA NI TIENE PULSO: Alternar 2 soplos y 15 compresiones. Efectuar 4 series y chequear si respira y tiene pulso. Controlar cada pocos minutos. SI LA VÍCTIMA REACCIONA: Ubicarla en posición de recuperación.', 'Diagrama circular que muestra los pasos de primeros auxilios para una emergencia médica, incluyendo reanimación cardiopulmonar.');
INSERT INTO "stimuli" ("id", "subject_id", "source_document_id", "title", "content_text", "media_type", "media_path", "instructions", "created_at", "source_page", "visual_transcription", "visual_description") VALUES ('5deabfa3-97fc-4777-96fb-0720cd526657', 1, 'f59ac90b-509a-493d-a75b-ae85c4c0cadf', 'Gran Hermano', '1984 es una novela futurista que tiene lugar en una sociedad totalitaria. Los ciudadanos de esta sociedad son controlados por una figura omnipresente conocida como el Gran Hermano. En el siguiente apartado, un miembro defensor del orden le explica al protagonista el principal propósito del régimen. No habrá lealtad; no existirá más fidelidad que la que se debe al Partido, ni más amor que el amor al Gran Hermano. No habrá risa, excepto la risa triunfal cuando se derrota a un enemigo. No habrá arte, ni literatura, ni ciencia. No habrá ya distinción entre la belleza y la fealdad. Todos los placeres serán destruidos. Pero siempre, no lo olvides, Winston, siempre habrá el afán de poder, la sed de dominio, que aumentará constantemente y se hará cada vez más sutil. Siempre existirá la emoción de la victoria, la sensación de pisotear a un enemigo indefenso. Si quieres hacerte una idea de cómo será el futuro, figúrate una bota aplastando un rostro humano... incesantemente.', 'none', NULL, 'RESPONDE LAS PREGUNTAS 15 Y 16 DE ACUERDO CON LA SIGUIENTE INFORMACIÓN', '2026-11-10 13:37:30+00', 17, NULL, NULL);
INSERT INTO "stimuli" ("id", "subject_id", "source_document_id", "title", "content_text", "media_type", "media_path", "instructions", "created_at", "source_page", "visual_transcription", "visual_description") VALUES ('0196ddad-0dee-44d5-9fa8-ab7a6d85752b', 1, 'f59ac90b-509a-493d-a75b-ae85c4c0cadf', 'Calvin and Hobbes', 'Historieta de Calvin y Hobbes sobre economía.', 'image', 'extracted/f59ac90b-509a-493d-a75b-ae85c4c0cadf/page-15_obj54.jpg', 'RESPONDE LA PREGUNTA 13 DE ACUERDO CON LA SIGUIENTE INFORMACIÓN', '2026-11-10 13:37:29+00', 15, 'Viñeta 1: ¿15 dólares por un vaso? Sí, 15 dólares ¿Quieres uno? Viñeta 2: ¿Pero cómo justificas 15 dólares por una limonada? Ley de la oferta y la demanda. Viñeta 3: ¡Pero dónde está la demanda?! ¡No veo ninguna demanda! Hay muchísima demanda. Viñeta 4: ¿Sí? ¡Claro! Como único accionista en esta empresa, ¡DEMANDO enormes beneficios por mi inversión!! Viñeta 5: Y como presidente de esta empresa, ¡DEMANDO un salario anual exorbitante! Viñeta 6: Y como soy mi propio empleado, ¡DEMANDO un alto salario y toda clase de beneficios que la compañía pueda dar! Y además hay gastos indirectos y costos de producción elevados. Viñeta 7: Si ¡pero eso es solo un limón en agua del grifo! Ya, pero tengo que recortar gastos de algún sitio si quiero ser competitivo. Viñeta 8: ¿Y si me enfermo por beber "eso"? "No hay garantías" es nuestro lema... Además debería cobrarla más cara si tuviera que cumplir con sanidad y medio ambiente. Viñeta 9: ¡Tú estás mal de la cabeza! Me voy a casa a beber lo que sea. ¡Vale! ¡Déjame sin trabajo y sin negocio! La gente anti-sistema como tú es quien arruina la economía! Viñeta 10: (Limonada 15 dólares). Viñeta 11: (Calvin solo). Viñeta 12: NECESITO UN SUBSIDIO.', 'Historieta de 12 viñetas donde Calvin intenta vender limonada a precios exorbitantes usando argumentos económicos absurdos.');
INSERT INTO "stimuli" ("id", "subject_id", "source_document_id", "title", "content_text", "media_type", "media_path", "instructions", "created_at", "source_page", "visual_transcription", "visual_description") VALUES ('ac2dadae-f916-4a27-a7f6-1029c1f03cab', 1, 'f59ac90b-509a-493d-a75b-ae85c4c0cadf', 'Caricatura de Quino', 'Texto de la caricatura: - LLEGÓ HABLANDO DE COSAS MUY RARAS,...BONDAD, AMOR, TOLERANCIA, CARIDAD, CUANDO AQUI LO QUE NECESITAMOS ES SEGURIDAD, CASA, PAN Y TRABAJO. PERO LO QUE NOS HIZO SOSPECHAR ENSEGUIDA DE ÉL ES QUE NO RECORDAMOS HABERLO VISTO SIQUIERA UNA VEZ EN TELEVISIÓN.', 'image', 'extracted/f59ac90b-509a-493d-a75b-ae85c4c0cadf/page-16_obj57.png', 'RESPONDE LA PREGUNTA 14 DE ACUERDO CON LA SIGUIENTE INFORMACIÓN', '2026-11-10 13:37:30+00', 16, 'Texto: - LLEGÓ HABLANDO DE COSAS MUY RARAS,...BONDAD, AMOR, TOLERANCIA, CARIDAD, CUANDO AQUI LO QUE NECESITAMOS ES SEGURIDAD, CASA, PAN Y TRABAJO. PERO LO QUE NOS HIZO SOSPECHAR ENSEGUIDA DE ÉL ES QUE NO RECORDAMOS HABERLO VISTO SIQUIERA UNA VEZ EN TELEVISIÓN.', 'Caricatura de Quino que muestra a una multitud linchando a un ángel caído en el suelo.');
INSERT INTO "stimuli" ("id", "subject_id", "source_document_id", "title", "content_text", "media_type", "media_path", "instructions", "created_at", "source_page", "visual_transcription", "visual_description") VALUES ('80832ea4-72b4-45a2-9659-e47e1770bdea', 1, 'f59ac90b-509a-493d-a75b-ae85c4c0cadf', 'Sobre la fotografía', 'Si las fotografías permiten la posesión imaginaria de un pasado irreal, también ayudan a tomar posesión de un espacio donde la gente está insegura. Así, la fotografía se desarrolla en conjunción con una de las actividades modernas más características: el turismo. Por primera vez en la historia, grupos numerosos de gente abandonan sus entornos habituales por breves periodos. Parece decididamente anormal viajar por placer sin llevar una cámara. Las fotografías son la prueba irrecusable de que se hizo la excursión, se cumplió el programa, se gozó del viaje. Las fotografías documentan secuencias de consumo realizadas en ausencia de la familia, los amigos, los vecinos. Pero la dependencia de la cámara, en cuanto aparato que da realidad a las experiencias, no disminuye cuando la gente viaja más. El acto de fotografiar satisface las mismas necesidades para los cosmopolitas que acumulan trofeos fotográficos de su excursión en barco por el Nilo o sus catorce días en China, que para los turistas de clase media que hacen instantáneas de la Torre Eiffel o las cataratas del Niágara. El acto fotográfico, un modo de certificar la experiencia, es también un modo de rechazarla: cuando se confina a la búsqueda de lo fotogénico, cuando se convierte la experiencia en una imagen, un recuerdo. El viaje se transforma en una estrategia para acumular fotos. La propia actividad fotográfica es tranquilizadora, y mitiga esa desorientación general que se suele agudizar con los viajes. La mayoría de los turistas se sienten obligados a poner la cámara entre ellos y toda cosa destacable que les sale al paso. Al no saber cómo reaccionar, hacen una foto. Así, la experiencia cobra forma: alto, una fotografía, adelante. El método seduce sobre todo a gente subyugada a una ética de trabajo implacable: alemanes, japoneses y estadounidenses. El empleo de una cámara atenúa su ansiedad provocada por la inactividad laboral cuando están en vacaciones y presuntamente divirtiéndose. Cuentan con una tarea que parece una simpática imitación del trabajo: pueden hacer fotos.', 'none', NULL, 'RESPONDE LAS PREGUNTAS 17 Y 18 DE ACUERDO CON LA SIGUIENTE INFORMACIÓN', '2026-11-10 13:37:30+00', 18, NULL, NULL);
INSERT INTO "stimuli" ("id", "subject_id", "source_document_id", "title", "content_text", "media_type", "media_path", "instructions", "created_at", "source_page", "visual_transcription", "visual_description") VALUES ('cd69334b-65d5-48b6-ad6a-05403c97903a', 1, 'f59ac90b-509a-493d-a75b-ae85c4c0cadf', 'Caricatura de Quino', 'Caricatura de Quino.', 'image', 'extracted/f59ac90b-509a-493d-a75b-ae85c4c0cadf/page-22_obj70.jpg', 'RESPONDE LA PREGUNTA 21 DE ACUERDO CON LA SIGUIENTE INFORMACIÓN', '2026-11-10 13:37:32+00', 22, NULL, 'Caricatura de Quino que muestra a un niño pequeño frente a un hombre adulto sentado en un sillón, en una habitación con paredes y techo cuadriculados.');
INSERT INTO "stimuli" ("id", "subject_id", "source_document_id", "title", "content_text", "media_type", "media_path", "instructions", "created_at", "source_page", "visual_transcription", "visual_description") VALUES ('aedf5759-55b5-418c-b720-1dea39f2ca0c', 1, 'f59ac90b-509a-493d-a75b-ae85c4c0cadf', 'Entre la crónica y la ideología', 'Fray Pedro de Aguado fue un misionero español que vivió en el Nuevo Reino de Granada entre 1560 y 1590, aproximadamente. Se le atribuye la autoría de la Recopilación historial,*un extenso compendio de crónicas donde se refieren los hechos de la temprana colonización española en los actuales territorios de Colombia y Venezuela. Las narraciones de la Recopilación giran alrededor de la entrada de los colonizadores españoles en territorios del “Nuevo Mundo”, del sometimiento de sus pobladores ancestrales y la subsiguiente fundación de ciudades coloniales, ofreciendo por lo general descripciones de las sociedades indígenas y su entorno natural. En el relato de las campañas del capitán Galarza y sus soldados en los actuales territorios del Tolima, Aguado se refiere de esta manera a los indios de la región: Son estos indios de Ibagué grandes carniceros de carne humana y de cualquier otra carne; tienen algodón, aunque poco, de que hacen algunas mantas para su vestir; las indias son muy feas, y traen en la cabeza unos bonetes de venado con que aprietan y axen los cabellos; no hay entre ellos caciques, como entre otros indios, mas son mandados de algunos indios principales que entre ellos hay, a los cuales obedecen cuando les parece y les da gusto. Es tierra muy áspera y fragosa, en la que estos indios habitan, y todas sierras peladas. En su estudio Los indios medievales de fray Pedro de Aguado**, el historiador Jaime Humberto Borja sostuvo que la Recopilación historial no puede ser tomada como una fuente fiable para el conocimiento de los eventos históricos; ante todo, debe asumirse como un texto que respondía ideológica y culturalmente a una tradición europea que poco tenía que ver con el mundo que pretendía representar: el del indígena y su entorno natural. Frente a descripciones como la que acabamos de citar, afirma Borja que el de Aguado “es un indio retórico, que surge de una realidad textual y no de una realidad aprehendida por la experiencia”. Además, la construcción narrativa del indio de la crónica de Aguado reúne imágenes conocidas por la tradición cristiana y los imaginarios bíblicos: “El canibalismo, las exacerbadas costumbres, la fiereza de sus armas, su alianza con traidores, el engaño. En el indio recae la descripción de los vicios físicos y morales de toda la extensión natural. (…) Para reafirmar sus posiciones, Aguado presenta una naturaleza tan salvaje como sus habitantes”.', 'none', NULL, 'RESPONDE LAS PREGUNTAS 19 Y 20 DE ACUERDO CON LA SIGUIENTE INFORMACIÓN', '2026-11-10 13:37:31+00', 20, NULL, NULL);
INSERT INTO "stimuli" ("id", "subject_id", "source_document_id", "title", "content_text", "media_type", "media_path", "instructions", "created_at", "source_page", "visual_transcription", "visual_description") VALUES ('e206d16a-6c01-4c6d-a2ec-feabda4c4094', 1, 'f59ac90b-509a-493d-a75b-ae85c4c0cadf', 'Frases filosóficas', '» Las filosofías comienzan en filosofía y acaban en retórica. (59) » La filosofía es actitud solitaria. » La adhesión de cualquier muchedumbre a una doctrina la convierte en mitología. (110) » Los sistemas filosóficos difieren los unos de los otros menos en la manera de resolver que en la manera de escamotear los problemas. (117) » Los que se ocupan de filosofía no la tomarían tan en serio, si generalmente no vivieran de ella como profesión. (130) » En filosofía lo que no sea fragmento es estafa. (162)', 'none', NULL, 'RESPONDE LA PREGUNTA 23 DE ACUERDO CON LA SIGUIENTE INFORMACIÓN', '2026-11-10 13:37:33+00', 24, NULL, NULL);
INSERT INTO "stimuli" ("id", "subject_id", "source_document_id", "title", "content_text", "media_type", "media_path", "instructions", "created_at", "source_page", "visual_transcription", "visual_description") VALUES ('424c9362-7958-4a78-8c44-216940202bd0', 1, 'f59ac90b-509a-493d-a75b-ae85c4c0cadf', 'Aprendiendo de los chimpancés', 'Cuando inicié mi estudio sobre chimpancés salvajes en 1960, en el Centro de Investigaciones Gombe Stream, no era permitido, al menos no en los círculos de etología, hablar sobre la mente de los animales. Solo los humanos tienen mentes. Ni tampoco era del todo correcto hablar acerca de la personalidad de los animales. Por supuesto que todos sabían que ellos tienen sus caracteres únicos —todos los que alguna vez hubieran tenido un perro u otra mascota eran conscientes de ello—. Pero los etólogos, luchando por hacer de la suya una ciencia ‘dura’, se mantuvieron alejados de la tarea de tratar de explicar esas cosas objetivamente. Un respetado etólogo, al mismo tiempo que reconocía que había una “variabilidad entre animales individuales”, escribió que era mejor que este hecho se “escondiera debajo de la alfombra”. Qué ingenua era. Como no había tenido una educación científica de pregrado, no me di cuenta de que en teoría los animales no debían tener personalidades, pensar o sentir emociones o dolor. No tenía idea de que hubiera sido más apropiado —una vez que llegara a conocerla o conocerlo— asignarle a cada uno de los chimpancés un número en lugar de un nombre. No me di cuenta de que no era científico discutir sobre el comportamiento en términos de motivación o propósito. No era respetable, en círculos científicos, hablar sobre la personalidad de los animales. Eso era algo que estaba reservado para los humanos. Tampoco tenían mente, así que no eran capaces de pensamiento racional. Y hablar acerca de sus emociones era sentirse culpable del peor tipo de antropomorfismo (atribuirles características humanas a los animales). En los comentarios editoriales al primer artículo que escribí con fines de publicación, se exigía que todo “él” o “ella” fuera reemplazado por “ello” y que todo “quien” fuera reemplazado por “que”. Enfurecida, taché uno a uno los “ello” y “que” y reescribí los pronombres originales. Dado que no me interesaba forjarme un nicho personal en el mundo de la ciencia, sino que simplemente quería vivir entre chimpancés y aprender sobre ellos, la posible reacción del editor de la muy ilustrada revista me era indiferente. El artículo, cuando finalmente fue publicado, les confirió a los chimpancés la dignidad de sus géneros correspondientes y correctamente los promovió del estatus de meras “cosas” a su existencia esencial.', 'none', NULL, 'RESPONDE LA PREGUNTA 24 DE ACUERDO CON LA SIGUIENTE INFORMACIÓN', '2026-11-10 13:37:33+00', 25, NULL, NULL);
INSERT INTO "stimuli" ("id", "subject_id", "source_document_id", "title", "content_text", "media_type", "media_path", "instructions", "created_at", "source_page", "visual_transcription", "visual_description") VALUES ('23a77e31-62c1-4fe3-a24e-eecab91e7e0e', 1, 'f59ac90b-509a-493d-a75b-ae85c4c0cadf', 'La historia del arte', 'A mucha gente le gusta ver en los cuadros lo que también le gustaría ver en la realidad. Se trata de una preferencia perfectamente comprensible. A todos nos atrae lo bello en la naturaleza y agradecemos a los artistas que lo recojan en sus obras. Esos mismos artistas no nos censurarían por nuestros gustos. Cuando el gran artista flamenco Rubens dibujó a su hijo, estaba orgulloso de sus agradables acciones y deseaba que también nosotros admiráramos al pequeño. Pero esta inclinación a los temas bonitos y atractivos puede convertirse en nociva si nos conduce a rechazar obras que representan asuntos menos agradables. El gran pintor alemán Alberto Durero seguramente dibujó a su madre con tanta devoción y cariño como Rubens a su hijo. Su verista estudio de la vejez y la decrepitud puede producirnos tan viva impresión que nos haga apartar los ojos de él y, sin embargo, si reaccionamos contra esta primera aversión, quedaremos recompensados con creces, pues el dibujo de Durero, en su tremenda sinceridad, es una gran obra. En efecto, de pronto descubrimos que la hermosura de un cuadro no reside realmente en la belleza de su tema. No sé si los golfillos que el pintor español Murillo se complacía en pintar eran estrictamente bellos o no, pero tal como fueron pintados por él, poseen desde luego gran encanto.', 'none', NULL, 'RESPONDE LAS PREGUNTAS 26 A 28 DE ACUERDO CON LA SIGUIENTE INFORMACIÓN', '2026-11-10 13:37:34+00', 27, NULL, NULL);
INSERT INTO "stimuli" ("id", "subject_id", "source_document_id", "title", "content_text", "media_type", "media_path", "instructions", "created_at", "source_page", "visual_transcription", "visual_description") VALUES ('a9da7d8c-9402-49e0-9e75-dcb9e4d54126', 1, 'f59ac90b-509a-493d-a75b-ae85c4c0cadf', 'El Anillo de Giges: La Naturaleza de la Justicia', 'Nadie es justo por voluntad sino porque no tiene el poder de cometer injusticias. Esto lo percibiremos mejor si nos imaginamos las cosas del siguiente modo: demos tanto al justo como al injusto el poder de hacer lo que cada uno de ellos quiere, y a continuación sigámoslos para observar hasta dónde lo lleva a cada uno el deseo. Entonces sorprenderemos al justo tomando el mismo camino que el injusto, siguiendo sus propios intereses, lo que toda criatura persigue por naturaleza como un bien, pero que la fuerza de la ley obliga a seguir el camino del respeto por la igualdad. El poder del que hablo sería efectivo al máximo si aquellos hombres adquirieran una fuerza tal como la que se dice que cierta vez tuvo Giges, el antepasado del lidio. Giges era un pastor que servía al entonces rey de Lidia. Un día sobrevino una gran tormenta y un terremoto que rasgó la tierra y produjo un abismo en el lugar en que Giges llevaba el ganado a pastorear. Asombrado al ver esto, descendió al abismo y halló, entre otras maravillas que narran los mitos, un caballo de bronce, hueco y con ventanillas, a través de las cuales divisó adentro un cadáver de tamaño más grande que el de un hombre, según parecía, y que no tenía nada excepto un anillo de oro en la mano. Giges le quitó el anillo y salió del abismo. Ahora bien, los pastores hacían su reunión habitual para dar al rey el informe mensual concerniente a la hacienda, cuando llegó Giges llevando el anillo. Tras sentarse entre los demás, casualmente volvió el engaste del anillo hacia el interior de su mano. Al suceder esto se tornó invisible para los que estaban sentados allí, quienes se pusieron a hablar de él como si se hubiera ido. Giges se asombró, y luego, examinando el anillo, dio vuelta al engaste hacia afuera y tornó a hacerse visible. Al advertirlo, experimentó con el anillo para ver si tenía tal propiedad, y comprobó que así era: cuando giraba el engaste hacia adentro, su dueño se hacía invisible, y cuando lo giraba hacia afuera, se hacía visible. En cuanto se hubo cerciorado de ello, maquinó el modo de formar parte de los que fueron a la residencia del rey como informantes y, una vez allí, sedujo a la reina y con ayuda de ella mató al rey y se apoderó del reino. Por consiguiente, si hubiese dos anillos como el de Giges y se diera uno a un hombre justo y otro a uno injusto, ninguno perseveraría en la justicia ni soportaría abstenerse de bienes ajenos, cuando podría tanto apoderarse impunemente de lo que quisiera del mercado, como, al entrar en las casas, acostarse con la mujer que prefiriera, y tanto matar a unos como librar de las cadenas a otros, según su voluntad, y hacer todo como si fuera igual a un dios entre los hombres. En esto, el hombre justo no haría nada diferente del injusto, sino que ambos marcharían por el mismo camino. E incluso se diría que esto es una importante prueba de que nadie es justo si no es forzado a serlo, por no considerarse a la justicia como un bien individual, ya que allí donde cada uno se cree capaz de cometer injusticias, las comete. En efecto, todo hombre piensa que la injusticia le brinda más ventajas individuales que la justicia, y está en lo cierto, si habla de acuerdo con esta teoría.', 'none', NULL, 'RESPONDE LAS PREGUNTAS 29 A 33 DE ACUERDO CON LA SIGUIENTE INFORMACIÓN', '2026-11-10 13:37:34+00', 29, NULL, NULL);
INSERT INTO "stimuli" ("id", "subject_id", "source_document_id", "title", "content_text", "media_type", "media_path", "instructions", "created_at", "source_page", "visual_transcription", "visual_description") VALUES ('55d94c33-a675-4b5a-a0ba-c4f5a740dd03', 1, 'f59ac90b-509a-493d-a75b-ae85c4c0cadf', 'El matrimonio: más allá del amor', 'En nuestra sociedad, se tiende a pensar que el matrimonio, la base de la familia, se sostiene si hay confianza mutua y buena comunicación, así como si ambos miembros de la pareja trabajan unidos para resolver los conflictos y pasan tiempo juntos. En resumen, su piedra angular es un amor maduro y sincero. No obstante, la idea de que este deba ser la razón última del enlace es bastante reciente: aparece en el siglo XVIII y se afianza en el XIX, con el movimiento romántico. Hasta entonces, el matrimonio era ante todo una institución económica y política demasiado trascendente como para dejarla en manos de los dos individuos implicados. En general, resultaba inconcebible que semejante acuerdo se basara en algo tan irracional como el enamoramiento. De hecho, no se inventó ni para que los hombres protegieran a las mujeres ni para que las explotaran. Se trataba de una alianza entre grupos que iba más allá de los familiares más cercanos o incluso los pequeños grupos. Para las élites, era una manera excelente de consolidar la riqueza, fusionar recursos y forjar uniones políticas. Desde la Edad Media, la dote de boda de la mujer constituía el mayor ingreso de dinero, bienes o tierras que un hombre iba a recibir en toda su vida. Para los más pobres, también suponía una transacción económica que debía ser beneficiosa para la familia. Así, se solía casar al hijo con la hija de quien tenía un campo colindante. El matrimonio se convirtió en la estructura que garantizaba la supervivencia de la familia extendida, que incluye abuelos, hermanos, sobrinos… Al contrario de lo que solemos creer, la imagen del marido trabajando fuera de la casa y la mujer haciéndose cargo de la misma es un producto reciente, de los años 50. Hasta entonces, la familia no se sostenía con un único proveedor, sino que todos sus integrantes contribuían al único negocio de la que esta dependía. Que el matrimonio no se basara en el amor no quiere decir que las personas no se enamoraran. Sin embargo, en algunas culturas se trata de algo incompatible con el matrimonio. En la China tradicional, por ejemplo, una atracción excesiva entre los esposos era tenida como una amenaza al respeto y solidaridad debida a la familia. Es más, en tal ambiente, la palabra amor solo se aplicaba para describir las relaciones ilícitas. Fue en la década de 1920 cuando se inventó un término para designar el cariño entre cónyuges. Una idea tan radicalmente nueva exigía un vocabulario especial. Aún hoy, muchas sociedades desaprueban la idea de que el amor sea el centro del matrimonio. Es el caso de los fulbes africanos, del norte de Camerún. “Muchas de sus mujeres niegan vehementemente cualquier apego hacia el marido”, asegura Helen A. Regis, del Departamento de Geografía y Antropología de la Universidad Estatal de Luisiana. Otras, en cambio, aprueban el amor entre esposos, pero nunca antes de que el matrimonio haya cumplido su objetivo primordial.', 'none', NULL, 'RESPONDE LAS PREGUNTAS 34 A 41 DE ACUERDO CON LA SIGUIENTE INFORMACIÓN', '2026-11-10 13:37:35+00', 32, NULL, NULL);
INSERT INTO "stimuli" ("id", "subject_id", "source_document_id", "title", "content_text", "media_type", "media_path", "instructions", "created_at", "source_page", "visual_transcription", "visual_description") VALUES ('c28f54ac-e64a-40f1-90be-1ce56fd0b66f', 1, 'f59ac90b-509a-493d-a75b-ae85c4c0cadf', 'Historieta de filósofo', 'Historieta sobre un filósofo.', 'image', 'extracted/f59ac90b-509a-493d-a75b-ae85c4c0cadf/page-26_obj82.jpg', 'RESPONDE LA PREGUNTA 25 DE ACUERDO CON LA SIGUIENTE INFORMACIÓN', '2026-11-10 13:37:34+00', 26, 'Viñeta 1: ¿Pero a qué viene toda esta cháchara del huevo? Viñeta 2: Me enseñaste a usar la razón como una forma de libertad. Y ahora, Crates, me libero de ti. Viñeta 3: ¿Qué dices? Viñeta 4: Que no puedes jalar a un filósofo de la ropa, sino de los oídos: mi cuerpo puede seguirte, pero mi mente ya no. Viñeta 5: Todo lo que existe se divide en lo que depende de nosotros y en lo que no. Viñeta 6: De nosotros dependen el juicio, el deseo y todo lo que hacemos. Viñeta 7: Por eso depende de mí separarme de ti, Crates.', 'Historieta de 7 viñetas con un filósofo barbudo y otro personaje.');
INSERT INTO "stimuli" ("id", "subject_id", "source_document_id", "title", "content_text", "media_type", "media_path", "instructions", "created_at", "source_page", "visual_transcription", "visual_description") VALUES ('d3c73aaa-82d4-41ed-9f3a-3c55723bcb7e', 2, 'b352295c-6b85-480e-a635-37ed53ca134c', 'Capacitación en informática básica', 'Para capacitar en informática básica a los trabajadores de algunas dependencias de una empresa, se contrata una institución que ofrece un plan educativo de 4 módulos (ver Tabla).
INSERT INTO "stimuli" ("id", "subject_id", "source_document_id", "title", "content_text", "media_type", "media_path", "instructions", "created_at", "source_page", "visual_transcription", "visual_description") VALUES ('56b5860a-39ae-42f7-b3f9-1bb0d28b4810', 2, 'b352295c-6b85-480e-a635-37ed53ca134c', 'Información de transporte de mango y banano', 'Para transportar mango y banano desde un pueblo cercano a dos ciudades, W y Z, un comerciante utiliza tres (3) camiones con capacidad de 5 toneladas cada uno; por cada camión contrata dos trabajadores en cada viaje. El comerciante compra a $ 400.000 la tonelada de banano y a $ 500.000, la de mango. En la tabla se muestra el precio de venta por tonelada de cada producto y los gastos de transporte y de trabajadores para cada ciudad.', 'table', NULL, 'RESPONDE LAS PREGUNTAS 9 A 13 DE ACUERDO CON LA SIGUIENTE INFORMACIÓN', '2026-11-11 12:47:19+00', 10, 'Ciudad W: Precio banano $ 1.000.000, Precio mango $ 1.300.000, Costo transporte $ 150.000, Pago trabajador $ 180.000 | Ciudad Z: Precio banano $ 1.200.000, Precio mango $ 1.350.000, Costo transporte $ 180.000, Pago trabajador $ 200.000', 'Tabla con precios de venta y costos operativos para ciudades W y Z.');
INSERT INTO "stimuli" ("id", "subject_id", "source_document_id", "title", "content_text", "media_type", "media_path", "instructions", "created_at", "source_page", "visual_transcription", "visual_description") VALUES ('8610642c-b120-402f-8623-0448a6473052', 1, 'f59ac90b-509a-493d-a75b-ae85c4c0cadf', 'Traumatismos causados por el tránsito: los hechos', 'Infografía sobre estadísticas de accidentes de tránsito.', 'image', 'extracted/f59ac90b-509a-493d-a75b-ae85c4c0cadf/page-36_obj104.png', 'RESPONDE LAS PREGUNTAS 42 A 49 DE ACUERDO CON LA SIGUIENTE INFORMACIÓN', '2026-11-10 13:37:35+00', 36, 'Traumatismos causados por el tránsito: los hechos. Cada año hay 1,24 millones de muertes por accidentes de tránsito. 3 de 4 de los fallecidos en accidentes de tránsito son del sexo masculino. 1a causa de muerte en el grupo etario de 15-29 años. Los países de ingresos medios sólo tienen la mitad de los vehículos existentes en el mundo y a pesar de eso sufren el 80% de las muertes por accidente de tránsito. Gráfica de vehículos: 52% (círculo). Gráfica de muertes: 80% (círculo). Gráfica de barras: Países de ingresos altos (20,1), Países de ingresos medios (18,3), Países de ingresos bajos (8,7). Muertes por accidentes de tránsito, por 100.000 habitantes. Mapa: Europa (10,3), Mediterráneo Oriental (21,3), Asia Sudoriental (18,5), Pacífico Occidental (18,5), África (24,1), Américas (16,1). El 50% de los fallecidos por accidentes de tránsito son peatones, ciclistas y motociclistas.', 'Infografía con datos estadísticos sobre accidentes de tránsito a nivel mundial, incluyendo gráficas de barras, mapas y diagramas circulares.');
INSERT INTO "stimuli" ("id", "subject_id", "source_document_id", "title", "content_text", "media_type", "media_path", "instructions", "created_at", "source_page", "visual_transcription", "visual_description") VALUES ('fde015d4-54f5-42da-b90f-f44b7e198b91', 1, 'f59ac90b-509a-493d-a75b-ae85c4c0cadf', 'Tratado contra el método', 'El conocimiento no consiste en una serie de teorías autoconsistentes que tiende a converger en una perspectiva ideal; no consiste en un acercamiento gradual hacia la verdad. Por el contrario, el conocimiento es un océano, siempre en aumento, de alternativas incompatibles entre sí (y tal vez inconmensurables); toda teoría particular, todo cuento de hadas, todo mito, forman parte del conjunto que obliga al resto a una articulación mayor, y todos ellos contribuyen, por medio de este proceso competitivo, al desarrollo de nuestro conocimiento. No hay nada establecido para siempre, ningún punto de vista puede quedar omitido en una explicación comprehensiva (...). Expertos y profanos, profesionales y diletantes, forjadores de utopías y mentirosos, todos ellos están invitados a participar en el debate y a contribuir al enriquecimiento de la cultura. La tarea del científico no ha de ser por más tiempo “la búsqueda de la verdad”, o “la glorificación de dios”, o “la sistematización de las observaciones” o “el perfeccionamiento de predicciones”. Todas estas cosas no son más que efectos marginales de una actividad a la que se dirige ahora su atención y que consiste en “hacer de la causa más débil la causa más fuerte”, como dijo el sofista, “por ello en apoyar el movimiento de conjunto”.', 'none', NULL, 'RESPONDE LAS PREGUNTAS 11 Y 12 DE ACUERDO CON LA SIGUIENTE INFORMACIÓN', '2026-11-10 13:37:28+00', 13, NULL, NULL);
INSERT INTO "stimuli" ("id", "subject_id", "source_document_id", "title", "content_text", "media_type", "media_path", "instructions", "created_at", "source_page", "visual_transcription", "visual_description") VALUES ('8beb8149-da7e-4ae9-9af7-365344dba9c2', 1, 'f59ac90b-509a-493d-a75b-ae85c4c0cadf', 'DEL DEBER DE LA DESOBEDIENCIA CIVIL (1849)', 'Creo de todo corazón en el lema “El mejor gobierno es el que tiene que gobernar menos”, y me gustaría verlo hacerse efectivo más rápida y sistemáticamente. Bien llevado, finalmente resulta en algo en lo que también creo: “El mejor gobierno es el que no tiene que gobernar en absoluto”. Y cuando los pueblos estén preparados para ello, ése será el tipo de gobierno que tengan. En el mejor de los casos, el gobierno no es más que una conveniencia, pero en su mayoría los gobiernos son inconvenientes y todos han resultado serlo en algún momento. Las objeciones que se han hecho a la existencia de un ejército permanente, que son varias y de peso, y que merecen mantenerse, pueden también por fin esgrimirse en contra del gobierno. El ejército permanente es sólo el brazo del gobierno establecido. El gobierno en sí, que es únicamente el modo escogido por el pueblo para ejecutar su voluntad, está igualmente sujeto al abuso y la corrupción antes de que el pueblo pueda actuar a través suyo. Somos testigos de la actual guerra con México, obra de unos pocos individuos comparativamente, que utilizan como herramienta al gobierno actual; en principio, el pueblo no habría aprobado esta medida. Pero, para hablar en forma práctica y como ciudadano, a diferencia de aquellos que se llaman “antigobiernistas”, yo pido, no como “antigobiernista” sino como ciudadano, y de inmediato, un mejor gobierno. Permítasele a cada individuo dar a conocer el tipo de gobierno que lo impulsaría a respetarlo y eso ya sería un paso ganado para obtener ese respeto. Después de todo, la razón práctica por la cual, una vez que el poder está en manos del pueblo, se le permite a una mayoría, y por un período largo de tiempo, regir, no es porque esa mayoría esté tal vez en lo correcto, ni porque le parezca justo a la minoría, sino porque físicamente son los más fuertes. Pero un gobierno en el que la mayoría rige en todos los casos no se puede basar en la justicia. No es deseable cultivar respeto por la ley más de por lo que es correcto. La única obligación a la que debo someterme es a la de hacer siempre lo que creo correcto. La ley nunca hizo al hombre un ápice más justo, y a causa del respeto por ella, aún el hombre bien dispuesto se convierte a diario en un agente de la injusticia.', 'none', NULL, 'RESPONDE LA PREGUNTA 22 DE ACUERDO CON LA SIGUIENTE INFORMACIÓN', '2026-11-10 13:37:32+00', 23, NULL, NULL);
INSERT INTO "stimuli" ("id", "subject_id", "source_document_id", "title", "content_text", "media_type", "media_path", "instructions", "created_at", "source_page", "visual_transcription", "visual_description") VALUES ('929c072d-7289-44e6-9b8d-287c53926ffd', 2, 'b352295c-6b85-480e-a635-37ed53ca134c', 'Promedios de los puntajes en el examen por cursos', 'Cuatro cursos, cada uno con igual número de estudiantes, presentan anualmente una prueba de matemáticas. La tabla muestra el puntaje promedio obtenido por cada curso.', 'table', NULL, 'Al revisar los puntajes de la tabla, una persona afirma que hubo un aumento en el puntaje respecto al año anterior. Esta afirmación es', '2026-11-11 12:47:18+00', 6, 'Curso: I, II, III, IV | Promedio año anterior: 63, 61, 50, 53 | Promedio año actual: 65, 45, 53, 54', 'Tabla que muestra los promedios de puntaje en el examen por cursos para el año anterior y el año actual.');
INSERT INTO "stimuli" ("id", "subject_id", "source_document_id", "title", "content_text", "media_type", "media_path", "instructions", "created_at", "source_page", "visual_transcription", "visual_description") VALUES ('839d8736-4532-4d14-bc42-c7be51349dba', 2, 'b352295c-6b85-480e-a635-37ed53ca134c', 'Horarios y precios de viaje a museo', 'Las directivas de un colegio tienen que organizar un viaje a un museo con 140 estudiantes, quienes deben dividirse en 3 grupos. Cada grupo irá en una franja diferente, pero el costo total de las entradas se asumirá equitativamente por los estudiantes. En la tabla se muestran los horarios disponibles, la máxima cantidad de estudiantes y los precios respectivos de cada horario.', 'table', NULL, 'Con el fin de que todos los estudiantes asistan y paguen el menor precio, las directivas eligieron las franjas 1, 3 y 4. ¿Esta elección garantiza que asistan todos los estudiantes al menor precio posible?', '2026-11-11 12:47:18+00', 7, 'Franja 1: 8:00 - 10:00, 50 estudiantes, $ 35.000 | Franja 2: 10:00 - 12:00, 40 estudiantes, $ 40.000 | Franja 3: 12:00 - 14:00, 30 estudiantes, $ 50.000 | Franja 4: 14:00 - 16:00, 60 estudiantes, $ 45.000', 'Tabla de franjas horarias con capacidad máxima de estudiantes y precio por entrada.');
INSERT INTO "questions" ("id", "root_question_id", "version", "is_current_version", "subject_id", "topic_id", "stimulus_id", "source_document_id", "order_in_group", "statement", "question_image_path", "difficulty", "explanation", "key_status", "status", "created_at", "updated_at", "source_page", "visual_transcription", "visual_description", "extraction_warnings") VALUES ('9669bf1d-3286-407d-ab36-c35dc387bc1a', 'dea01be7-e986-47f4-ae1f-449f4a8b4d6e', 1, TRUE, 2, NULL, '929c072d-7289-44e6-9b8d-287c53926ffd', 'b352295c-6b85-480e-a635-37ed53ca134c', 1, 'Al revisar los puntajes de la tabla, una persona afirma que hubo un aumento en el puntaje respecto al año anterior. Esta afirmación es', NULL, 'medium', 'El promedio total en el año anterior es superior al promedio total en el año actual, por lo que la afirmación es incorrecta.', 'verified', 'draft', '2026-11-11 12:47:19+00', '2026-11-11 12:47:19+00', 6, NULL, 'Tabla de promedios por curso.', NULL);
INSERT INTO "questions" ("id", "root_question_id", "version", "is_current_version", "subject_id", "topic_id", "stimulus_id", "source_document_id", "order_in_group", "statement", "question_image_path", "difficulty", "explanation", "key_status", "status", "created_at", "updated_at", "source_page", "visual_transcription", "visual_description", "extraction_warnings") VALUES ('8c22261d-c0a6-46f1-a7aa-93f34e5bf28b', '7c4c804f-741a-443f-aa7c-0b0bf9d7dea0', 1, TRUE, 2, NULL, NULL, 'b352295c-6b85-480e-a635-37ed53ca134c', 2, 'Una persona que vive en Colombia tiene inversiones en dólares en Estados Unidos, y sabe que la tasa de cambio del dólar respecto al peso colombiano se mantendrá constante este mes, siendo 1 dólar equivalente a 4.000 pesos colombianos y que su inversión, en dólares, le dará ganancias del 3 % en el mismo periodo. Un amigo le asegura que en pesos sus ganancias también serán del 3 %.
INSERT INTO "questions" ("id", "root_question_id", "version", "is_current_version", "subject_id", "topic_id", "stimulus_id", "source_document_id", "order_in_group", "statement", "question_image_path", "difficulty", "explanation", "key_status", "status", "created_at", "updated_at", "source_page", "visual_transcription", "visual_description", "extraction_warnings") VALUES ('96931879-388c-4602-b632-a4dec409bce0', '831f9bda-cb6f-409c-b902-1f305f6116fa', 1, TRUE, 2, NULL, '839d8736-4532-4d14-bc42-c7be51349dba', 'b352295c-6b85-480e-a635-37ed53ca134c', 3, 'Con el fin de que todos los estudiantes asistan y paguen el menor precio, las directivas eligieron las franjas 1, 3 y 4. ¿Esta elección garantiza que asistan todos los estudiantes al menor precio posible?', NULL, 'medium', 'Eligiendo la franja 2 en lugar de la franja 3 se obtiene un precio menor por estudiante y se cumple con la capacidad.', 'verified', 'draft', '2026-11-11 12:47:23+00', '2026-11-11 12:47:23+00', 7, NULL, 'Tabla con datos de franjas horarias y precios.', NULL);
INSERT INTO "questions" ("id", "root_question_id", "version", "is_current_version", "subject_id", "topic_id", "stimulus_id", "source_document_id", "order_in_group", "statement", "question_image_path", "difficulty", "explanation", "key_status", "status", "created_at", "updated_at", "source_page", "visual_transcription", "visual_description", "extraction_warnings") VALUES ('07e74439-0d27-4efc-b495-96791b76de4c', '5553969d-93db-47c9-8f09-2761f910467a', 1, TRUE, 2, NULL, 'd3c73aaa-82d4-41ed-9f3a-3c55723bcb7e', 'b352295c-6b85-480e-a635-37ed53ca134c', 4, 'La empresa pagará $4.200.000 por capacitar a los trabajadores de la dependencia “Insumos” en el módulo I, ¿cuántos empleados tiene esta dependencia?', NULL, 'medium', 'Costo por hora del módulo I = $35.000, intensidad horaria = 40 h. Costo por trabajador = 35.000 * 40 = $1.400.000. Total pagado = $4.200.000 / $1.400.000 = 3 trabajadores por curso, o dividiendo el costo total por el valor por estudiante. Analizando los límites de personas por curso (20 a 30): 4.200.000 / (40 * 35.000) = 3 grupos o similar, resultando en entre 61 y 90 trabajadores.', 'verified', 'draft', '2026-11-11 12:47:26+00', '2026-11-11 12:47:26+00', 8, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "root_question_id", "version", "is_current_version", "subject_id", "topic_id", "stimulus_id", "source_document_id", "order_in_group", "statement", "question_image_path", "difficulty", "explanation", "key_status", "status", "created_at", "updated_at", "source_page", "visual_transcription", "visual_description", "extraction_warnings") VALUES ('d63ec280-f122-4845-9bce-a2d2a13cde73', '6cfd7c2e-50b5-407f-9fb9-08de136aabe8', 1, TRUE, 2, NULL, 'd3c73aaa-82d4-41ed-9f3a-3c55723bcb7e', 'b352295c-6b85-480e-a635-37ed53ca134c', 5, 'Si se les cobrara a los 50 trabajadores de la dependencia “Recursos Humanos” la capacitación del módulo II, y todos pagaran el mismo valor, ¿cuánto debería pagar cada uno por esa capacitación?', NULL, 'medium', 'Cálculo basado en la intensidad horaria y valor por hora del módulo II repartido entre los trabajadores.', 'verified', 'draft', '2026-11-11 12:47:28+00', '2026-11-11 12:47:28+00', 8, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "root_question_id", "version", "is_current_version", "subject_id", "topic_id", "stimulus_id", "source_document_id", "order_in_group", "statement", "question_image_path", "difficulty", "explanation", "key_status", "status", "created_at", "updated_at", "source_page", "visual_transcription", "visual_description", "extraction_warnings") VALUES ('ce0efaa8-4a93-4153-bd70-4b3323c43031', '69d27059-132c-4bb1-8f68-2d1058ce8391', 1, TRUE, 2, NULL, 'd3c73aaa-82d4-41ed-9f3a-3c55723bcb7e', 'b352295c-6b85-480e-a635-37ed53ca134c', 6, 'La empresa paga $ 900.000 por la capacitación de los 40 funcionarios de la dependencia “Importaciones”. De acuerdo con el valor pagado, ¿cuál de los siguientes módulos corresponde al tomado por la dependencia "Importaciones"?', NULL, 'medium', 'Cálculo del costo por hora y comparación con los valores de la tabla.', 'verified', 'draft', '2026-11-11 12:47:30+00', '2026-11-11 12:47:30+00', 8, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "root_question_id", "version", "is_current_version", "subject_id", "topic_id", "stimulus_id", "source_document_id", "order_in_group", "statement", "question_image_path", "difficulty", "explanation", "key_status", "status", "created_at", "updated_at", "source_page", "visual_transcription", "visual_description", "extraction_warnings") VALUES ('2782b3e5-2d02-4b27-a77e-6a9d35f59a8f', '453ac628-ccfb-489d-9131-accdae04df39', 1, TRUE, 2, NULL, NULL, 'b352295c-6b85-480e-a635-37ed53ca134c', 7, 'El portalápices tiene base y boca cuadrada, por lo cual Eliécer afirma: “Como los perímetros de la base y la boca del portalápices están en relación 18/24 = 3/4, el área de la base debe ser también tres cuartas partes del área de la boca del portalápices”. ¿Es verdadera esta afirmación?', NULL, 'hard', 'Las longitudes de los lados están en razón 3/4, pero al tratarse de áreas (unidades cuadradas), la razón se eleva al cuadrado ((3/4)^2 = 9/16).', 'verified', 'draft', '2026-11-11 12:47:32+00', '2026-11-11 12:47:32+00', 9, 'Perímetro base: 18 cm, Perímetro boca: 24 cm.', 'Ilustración de un portalápices con base y boca cuadrada con un caucho elástico.', NULL);
