INSERT INTO "questions" ("id", "root_question_id", "version", "is_current_version", "subject_id", "topic_id", "stimulus_id", "source_document_id", "order_in_group", "statement", "question_image_path", "difficulty", "explanation", "key_status", "status", "created_at", "updated_at", "source_page", "visual_transcription", "visual_description", "extraction_warnings") VALUES ('7de59dc6-62db-4866-97ea-138e87d66121', 'e29f6738-45dc-416c-aa53-94acda22f657', 1, TRUE, 1, NULL, 'c28f54ac-e64a-40f1-90be-1ce56fd0b66f', 'f59ac90b-509a-493d-a75b-ae85c4c0cadf', 25, 'Teniendo en cuenta los planteamientos dados en la historieta, ¿cuál de los siguientes enunciados contradice la tesis central del texto?', NULL, 'medium', NULL, 'verified', 'published', '2026-11-10 13:38:15+00', '2026-11-10 14:24:20+00', 27, 'Diálogos de historieta filosófica entre pensadores clásicos griegos debatiendo sobre la realidad, el ser y la naturaleza humana.', 'Tira cómica que ilustra un diálogo filosófico entre dos personajes con túnicas y barbas clásicas en una reflexión humorística sobre la filosofía.', NULL);
INSERT INTO "questions" ("id", "root_question_id", "version", "is_current_version", "subject_id", "topic_id", "stimulus_id", "source_document_id", "order_in_group", "statement", "question_image_path", "difficulty", "explanation", "key_status", "status", "created_at", "updated_at", "source_page", "visual_transcription", "visual_description", "extraction_warnings") VALUES ('f0ce3ace-3b0a-4d8a-b4de-bf30148c8bdc', '67af88cb-f90e-466c-9955-6d6364077f83', 1, TRUE, 1, NULL, '8610642c-b120-402f-8623-0448a6473052', 'f59ac90b-509a-493d-a75b-ae85c4c0cadf', 42, 'Según la infografía, “los países de ingresos medios solo tienen la mitad de los vehículos existentes en el mundo y, a pesar de eso, sufren el 80 % de las muertes por accidente de tránsito”. En este enunciado, ¿qué función cumple la conjunción ‘a pesar de’?', NULL, 'medium', NULL, 'verified', 'published', '2026-11-10 13:38:42+00', '2026-11-10 14:24:20+00', 37, 'Traumatismos causados por el tránsito: los hechos. Cada año hay 1,24 millones de muertes por accidentes de tránsito. 3 de cada 4 de los fallecidos son del sexo masculino. Gráficas de barras por nivel de ingresos de los países.', 'Infografía oficial de la Organización Mundial de la Salud (OMS) con gráficas estadísticas, mapas y diagramas de barras que comparan las tasas de mortalidad y accidentes de tránsito según los ingresos de las naciones.', NULL);
INSERT INTO "questions" ("id", "root_question_id", "version", "is_current_version", "subject_id", "topic_id", "stimulus_id", "source_document_id", "order_in_group", "statement", "question_image_path", "difficulty", "explanation", "key_status", "status", "created_at", "updated_at", "source_page", "visual_transcription", "visual_description", "extraction_warnings") VALUES ('d92eacd5-364a-43b2-a262-6976eb9c7d58', 'adcc9b65-ed16-4339-9973-5be9c472b5b0', 1, TRUE, 1, NULL, '8610642c-b120-402f-8623-0448a6473052', 'f59ac90b-509a-493d-a75b-ae85c4c0cadf', 43, 'Si alguien lee la infografía y hace la siguiente descripción: «La infografía muestra datos sobre la frecuencia de los accidentes de tránsito en el mundo, y ejemplos relacionados. Además, informa sobre la mortalidad por género, por ingresos, por número de vehículos, por tipo de vehículo y por ubicación regional.» Usted diría que la descripción es insatisfactoria porque:', NULL, 'medium', NULL, 'verified', 'published', '2026-11-10 13:38:44+00', '2026-11-10 14:24:20+00', 37, 'Traumatismos causados por el tránsito: los hechos. Cada año hay 1,24 millones de muertes por accidentes de tránsito. 3 de cada 4 de los fallecidos son del sexo masculino. Gráficas de barras por nivel de ingresos de los países.', 'Infografía oficial de la Organización Mundial de la Salud (OMS) con gráficas estadísticas, mapas y diagramas de barras que comparan las tasas de mortalidad y accidentes de tránsito según los ingresos de las naciones.', NULL);
