INSERT INTO "questions" ("id", "root_question_id", "version", "is_current_version", "subject_id", "topic_id", "stimulus_id", "source_document_id", "order_in_group", "statement", "question_image_path", "difficulty", "explanation", "key_status", "status", "created_at", "updated_at", "source_page", "visual_transcription", "visual_description", "extraction_warnings") VALUES ('c4bf6db7-8918-4e28-b2e6-f86f7f0d10d2', '8144406b-139a-4acf-8606-769eb94aeb47', 1, TRUE, 2, NULL, NULL, 'b352295c-6b85-480e-a635-37ed53ca134c', 8, 'Un grupo de montañistas sabe que cada vez que aumenta la altitud en 100 m, la temperatura disminuye en 1 °C. Si el grupo se encuentra a una altitud de 1.000 m, donde la temperatura es de 20 °C, ¿cuál de las siguientes expresiones les permite determinar la temperatura que habrá cuando se encuentren a 4.000 m de altitud?', NULL, 'medium', 'La temperatura disminuye 1 °C por cada 100 m. Partiendo de 20 °C a 1.000 m, la expresión algebraica correspondiente es Temperatura = 20 - (Altitud - 1000)/100, equivalente a la opción C.', 'verified', 'draft', '2026-11-11 12:47:34+00', '2026-11-11 12:47:34+00', 9, NULL, NULL, NULL);
