INSERT INTO "questions" ("id", "root_question_id", "version", "is_current_version", "subject_id", "topic_id", "stimulus_id", "source_document_id", "order_in_group", "statement", "question_image_path", "difficulty", "explanation", "key_status", "status", "created_at", "updated_at", "source_page", "visual_transcription", "visual_description", "extraction_warnings") VALUES ('b27b6757-32d9-4a70-88d4-303650d988cb', '1c5dc513-24a8-4084-8ccc-5d472b796387', 1, TRUE, 2, NULL, NULL, 'b352295c-6b85-480e-a635-37ed53ca134c', 19, 'En una feria robótica, el robot P y el robot Q disputan un juego de tenis de mesa. En el momento que el marcador se encuentra 7 a 2 a favor del robot P, estos se reprograman de tal forma que por cada 2 puntos que anota el robot P, el robot Q anota 3. ¿Cuál de las siguientes ecuaciones permite determinar cuándo igualará en puntos el robot Q al robot P?', NULL, 'medium', 'Robot P tiene 7 puntos iniciales y anota x puntos adicionales (marcador total P = 7 + x). Robot Q tiene 2 puntos iniciales y anota puntos a razón de 3 por cada 2 de P, es decir, (3/2)x puntos (marcador total Q = 2 + (3/2)x). Igualando: 7 + x = 2 + (3/2)x.', 'verified', 'draft', '2026-11-11 12:47:55+00', '2026-11-11 12:47:55+00', 15, NULL, NULL, NULL);
