INSERT INTO "questions" ("id", "root_question_id", "version", "is_current_version", "subject_id", "topic_id", "stimulus_id", "source_document_id", "order_in_group", "statement", "question_image_path", "difficulty", "explanation", "key_status", "status", "created_at", "updated_at", "source_page", "visual_transcription", "visual_description", "extraction_warnings") VALUES ('8db9020e-c8fc-484a-a20d-74ff9d027d57', '7f180038-644b-4651-a4a5-04e7651fb951', 1, TRUE, 2, NULL, NULL, 'b352295c-6b85-480e-a635-37ed53ca134c', 34, 'Una regla usada en física indica que, para aumentar el nivel de intensidad del sonido en 10 dB (dB es decibelios, la unidad de medida del nivel de intensidad del sonido), es necesario que la intensidad medida se multiplique por 10. Ramiro es el encargado de aumentar en 20 dB la medida del nivel de intensidad del sistema de sonido de un evento y, según su interpretación de la regla, multiplica por 20 la intensidad actual del sistema. ¿Es correcta su interpretación?', NULL, 'medium', 'Un aumento de 20 dB corresponde a dos aumentos sucesivos de 10 dB, lo que implica multiplicar por 10 dos veces (10 * 10 = 100).', 'verified', 'draft', '2026-11-11 12:48:23+00', '2026-11-11 12:48:23+00', 24, NULL, NULL, NULL);
