INSERT INTO "questions" ("id", "root_question_id", "version", "is_current_version", "subject_id", "topic_id", "stimulus_id", "source_document_id", "order_in_group", "statement", "question_image_path", "difficulty", "explanation", "key_status", "status", "created_at", "updated_at", "source_page", "visual_transcription", "visual_description", "extraction_warnings") VALUES ('056e9dfe-f0cc-4787-b481-f37b87385d12', '81cd4078-96b3-4964-96c0-b4d58743caee', 1, TRUE, 2, NULL, NULL, 'b352295c-6b85-480e-a635-37ed53ca134c', 39, 'Un sistema de información requiere que los usuarios ingresen una contraseña de solo tres caracteres de entre las 26 letras posibles, en minúscula o mayúscula y los 10 dígitos del 0 al 9. Un ingeniero propone las siguientes posibles restricciones para la contraseña:
INSERT INTO "questions" ("id", "root_question_id", "version", "is_current_version", "subject_id", "topic_id", "stimulus_id", "source_document_id", "order_in_group", "statement", "question_image_path", "difficulty", "explanation", "key_status", "status", "created_at", "updated_at", "source_page", "visual_transcription", "visual_description", "extraction_warnings") VALUES ('350c49c8-dbed-42bc-9a7c-195cb0461df7', '91aebcb0-81cf-4b67-8c08-489f3742b461', 1, TRUE, 2, NULL, NULL, 'b352295c-6b85-480e-a635-37ed53ca134c', 40, 'Se puede encontrar números racionales mayores que un número entero k, de manera que sean cada vez más cercanos a él, calculando k + 1/j (con j entero positivo). Cuanto más grande sea j, más cercano a k será el racional construido. ¿Cuántos números racionales se pueden construir cercanos a k y menores que k + 1/11?', NULL, 'medium', 'Entre dos números reales siempre existe una cantidad infinita de números racionales (propiedad de densidad de los racionales).', 'verified', 'draft', '2026-11-11 12:48:34+00', '2026-11-11 12:48:34+00', 26, NULL, NULL, NULL);
