INSERT INTO "questions" ("id", "root_question_id", "version", "is_current_version", "subject_id", "topic_id", "stimulus_id", "source_document_id", "order_in_group", "statement", "question_image_path", "difficulty", "explanation", "key_status", "status", "created_at", "updated_at", "source_page", "visual_transcription", "visual_description", "extraction_warnings") VALUES ('5c9d0a6b-a412-483c-9004-2de4815434fd', '85ea23bb-cd9f-4c38-8dd1-ec11abaa556e', 1, TRUE, 2, NULL, NULL, 'b352295c-6b85-480e-a635-37ed53ca134c', 44, 'En un parque hay una rueda giratoria de 3 m de radio. La rueda está diseñada para 10 personas, cada una en un sector circular de igual área, como muestra la figura.
INSERT INTO "questions" ("id", "root_question_id", "version", "is_current_version", "subject_id", "topic_id", "stimulus_id", "source_document_id", "order_in_group", "statement", "question_image_path", "difficulty", "explanation", "key_status", "status", "created_at", "updated_at", "source_page", "visual_transcription", "visual_description", "extraction_warnings") VALUES ('7eb3d0d4-a34c-4511-96a4-bd40eb5e3dc3', 'dd270512-f6d8-4f46-86a3-98f929e162bb', 1, TRUE, 2, NULL, NULL, 'b352295c-6b85-480e-a635-37ed53ca134c', 45, 'Un colegio necesita enviar 5 estudiantes como representantes a un foro sobre la contaminación del medio ambiente. Se decidió que 2 estudiantes sean de grado décimo y 3 de grado undécimo. En décimo hay 5 estudiantes preparados para el foro y en undécimo hay 4. ¿Cuántos grupos diferentes pueden formarse para enviar al foro?', NULL, 'medium', 'Combinaciones: C(5, 2) * C(4, 3) = (5! / (2! * 3!)) * (4! / (3! * 1!)) = 10 * 4 = 40.', 'verified', 'draft', '2026-11-11 12:48:44+00', '2026-11-11 12:48:44+00', 29, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "root_question_id", "version", "is_current_version", "subject_id", "topic_id", "stimulus_id", "source_document_id", "order_in_group", "statement", "question_image_path", "difficulty", "explanation", "key_status", "status", "created_at", "updated_at", "source_page", "visual_transcription", "visual_description", "extraction_warnings") VALUES ('f848c86b-85c7-4797-aeca-7996a34e6d80', '0b8a2899-e039-4ba1-8dad-dc59e68180fc', 1, TRUE, 2, NULL, NULL, 'b352295c-6b85-480e-a635-37ed53ca134c', 46, 'En una feria, un niño recibe como premio una consola de videojuegos si gana en cada uno de los siguientes juegos:
INSERT INTO "questions" ("id", "root_question_id", "version", "is_current_version", "subject_id", "topic_id", "stimulus_id", "source_document_id", "order_in_group", "statement", "question_image_path", "difficulty", "explanation", "key_status", "status", "created_at", "updated_at", "source_page", "visual_transcription", "visual_description", "extraction_warnings") VALUES ('5b4c13d3-2a10-495d-bb18-5f25ce36c12d', '67de8e79-1463-4361-a4e2-450b4d921744', 1, TRUE, 2, NULL, NULL, 'b352295c-6b85-480e-a635-37ed53ca134c', 47, 'La expresión 10^3 = I / Io relaciona la sonoridad de un sonido de 30 decibeles con su intensidad (I) y la menor intensidad (Io) que percibe el oído humano. ¿Cuántas veces es el valor de I respecto a Io?', NULL, 'easy', '10^3 = 1.000, por lo que I = 1.000 * Io (mil veces).', 'verified', 'draft', '2026-11-11 12:48:48+00', '2026-11-11 12:48:48+00', 30, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "root_question_id", "version", "is_current_version", "subject_id", "topic_id", "stimulus_id", "source_document_id", "order_in_group", "statement", "question_image_path", "difficulty", "explanation", "key_status", "status", "created_at", "updated_at", "source_page", "visual_transcription", "visual_description", "extraction_warnings") VALUES ('64d4d2b0-289b-437f-a5e2-bf15798a9137', '8e189bfd-8e13-4f7c-b4e8-9b9caa86eb75', 1, TRUE, 2, NULL, NULL, 'b352295c-6b85-480e-a635-37ed53ca134c', 48, 'Entre los 16 estudiantes de un salón de clases se va a rifar una boleta para ingresar a un parque de diversiones. Cada estudiante debe escoger un número del 3 al 18. El sorteo se efectúa de la siguiente manera: se depositan 6 balotas en una urna, cada una numerada del 1 al 6; se extrae una balota, se mira el número y se vuelve a depositar en la urna. El experimento se repite dos veces más. La suma de los tres puntajes obtenidos determina el número ganador de la rifa. Si en la primera extracción del sorteo se obtuvo 2, ¿por qué es más probable que el estudiante que escogió el número 10 gane la rifa a que la gane el estudiante con el número 7?', NULL, 'hard', 'Dado que ya salió 2 en la primera extracción, faltan dos extracciones (con suma posible de 2 a 12). Para obtener 10, la suma de las dos siguientes extracciones debe ser 8 (con varias combinaciones posibles), mientras que para obtener 7 debe ser 5, teniendo el estudiante del 10 más combinaciones favorables.', 'verified', 'draft', '2026-11-11 12:48:49+00', '2026-11-11 12:48:49+00', 31, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "root_question_id", "version", "is_current_version", "subject_id", "topic_id", "stimulus_id", "source_document_id", "order_in_group", "statement", "question_image_path", "difficulty", "explanation", "key_status", "status", "created_at", "updated_at", "source_page", "visual_transcription", "visual_description", "extraction_warnings") VALUES ('52d31f2a-9cd0-412b-a01b-4453c29217d6', 'ca4b964b-3dfa-4586-9c1a-a616a24392a4', 1, TRUE, 2, NULL, NULL, 'b352295c-6b85-480e-a635-37ed53ca134c', 49, 'En determinada zona de una ciudad se construyen edificios de apartamentos en los que cada metro cuadrado tiene un costo de $ 800.000, y se asegura a los compradores que en esta zona anualmente, el metro cuadrado se valoriza un 5 % respecto al costo del año anterior. ¿Con cuál de las siguientes expresiones se representa el costo de un metro cuadrado en esa zona, transcurridos n años?', NULL, 'medium', 'Crecimiento exponencial con interés compuesto: Valor inicial * (1 + tasa)^n = 800.000 * (1 + 5/100)^n.', 'verified', 'draft', '2026-11-11 12:48:51+00', '2026-11-11 12:48:51+00', 31, NULL, NULL, NULL);
INSERT INTO "questions" ("id", "root_question_id", "version", "is_current_version", "subject_id", "topic_id", "stimulus_id", "source_document_id", "order_in_group", "statement", "question_image_path", "difficulty", "explanation", "key_status", "status", "created_at", "updated_at", "source_page", "visual_transcription", "visual_description", "extraction_warnings") VALUES ('66349af6-6496-4773-89de-ce10137694ba', '62f780c0-da79-437e-90df-45ebd7f8be2a', 1, TRUE, 2, NULL, NULL, 'b352295c-6b85-480e-a635-37ed53ca134c', 43, 'El área de los rectángulos que se pueden construir a partir del origen, los ejes y un punto que pertenece a la gráfica de la función f(x) = 5 / x, donde x > 0, se describe con la expresión Ax = xf(x).
