INSERT INTO "question_options" ("id", "question_id", "option_letter", "option_text", "option_image_path", "is_correct", "created_at") VALUES ('44512f68-89a7-4ce9-af21-e4090d498aed', '2782b3e5-2d02-4b27-a77e-6a9d35f59a8f', 'A', 'No, porque la medición se realiza con el mismo caucho y, por tanto, las áreas de la base y la boca deben ser iguales.', NULL, FALSE, '2026-11-11 12:47:32+00');
INSERT INTO "question_options" ("id", "question_id", "option_letter", "option_text", "option_image_path", "is_correct", "created_at") VALUES ('6c1bb39e-54cd-41a0-b0bb-c9f65da4a8c1', '2782b3e5-2d02-4b27-a77e-6a9d35f59a8f', 'B', 'Sí, porque el caucho se estira dependiendo del área que encierre, por lo que las relaciones de las áreas y los perímetros son iguales.', NULL, FALSE, '2026-11-11 12:47:32+00');
INSERT INTO "question_options" ("id", "question_id", "option_letter", "option_text", "option_image_path", "is_correct", "created_at") VALUES ('a7019283-9596-457a-96d2-792aaef37275', '2782b3e5-2d02-4b27-a77e-6a9d35f59a8f', 'C', 'No, porque la relación obtenida se cumple para las longitudes de los lados, pero al calcular las áreas, la razón obtenida se eleva al cuadrado.', NULL, TRUE, '2026-11-11 12:47:33+00');
INSERT INTO "question_options" ("id", "question_id", "option_letter", "option_text", "option_image_path", "is_correct", "created_at") VALUES ('c03df401-da61-466d-8ef7-223c5218c175', '2782b3e5-2d02-4b27-a77e-6a9d35f59a8f', 'D', 'Sí, porque como las figuras son semejantes, todas sus medidas deben tener la misma razón que los perímetros.', NULL, FALSE, '2026-11-11 12:47:33+00');
