INSERT INTO "question_options" ("id", "question_id", "option_letter", "option_text", "option_image_path", "is_correct", "created_at") VALUES ('7fe7a749-9c4e-4c94-bec2-376fa3c9d1fe', 'd303e20a-897c-42bf-99e4-057594514342', 'A', '“La avispa lleva al grillo a su madriguera, deja sus huevos, cierra la madriguera y luego se va para no volver”.', NULL, FALSE, '2026-11-10 13:37:41+00');
INSERT INTO "question_options" ("id", "question_id", "option_letter", "option_text", "option_image_path", "is_correct", "created_at") VALUES ('014657dc-0ecb-4710-b1db-699b1ccf8090', 'd303e20a-897c-42bf-99e4-057594514342', 'B', '“La avispa nunca piensa en llevar al grillo directamente a su madriguera. En una ocasión, este procedimiento fue repetido cuarenta veces, siempre con el mismo resultado”.', NULL, TRUE, '2026-11-10 13:37:41+00');
INSERT INTO "question_options" ("id", "question_id", "option_letter", "option_text", "option_image_path", "is_correct", "created_at") VALUES ('823cbbca-2e85-45fc-9b7e-da9979dc5f8b', 'd303e20a-897c-42bf-99e4-057594514342', 'C', '“Para la mente humana, tal rutina tan organizada y aparentemente llena de propósitos lleva consigo un sabor de lógica y de pensamiento”.', NULL, FALSE, '2026-11-10 13:37:42+00');
INSERT INTO "question_options" ("id", "question_id", "option_letter", "option_text", "option_image_path", "is_correct", "created_at") VALUES ('ecc55696-73ec-4af9-8519-17d873e41f2e', 'd303e20a-897c-42bf-99e4-057594514342', 'D', '“Por ejemplo, la rutina de la avispa consiste en llevar al grillo hacia la madriguera, dejarlo en la entrada, ir adentro a revisar que todo esté bien, salir y luego dejar el grillo adentro”.', NULL, FALSE, '2026-11-10 13:37:42+00');
