INSERT INTO "question_options" ("id", "question_id", "option_letter", "option_text", "option_image_path", "is_correct", "created_at") VALUES ('300a2e11-c6b1-434e-bda5-22097578caff', '9f8c0bac-17cd-4c59-ad4c-9ad4439fc67f', 'D', 'Siempre que una persona cuente con la libertad para cometer injusticias lo hará.', NULL, TRUE, '2026-11-10 13:38:26+00');
