INSERT INTO "question_options" ("id", "question_id", "option_letter", "option_text", "option_image_path", "is_correct", "created_at") VALUES ('0bbf1a19-f5d8-47c5-8eca-0eaac8965907', 'bcdd6a56-dc3c-4618-839d-629a808e8718', 'D', 'La justicia es un ideal inalcanzable, ya que toda persona, por más justa que aparente ser, tiene intereses propios que pueden llevarla a cometer injusticias.', NULL, FALSE, '2026-11-10 13:38:27+00');
INSERT INTO "question_options" ("id", "question_id", "option_letter", "option_text", "option_image_path", "is_correct", "created_at") VALUES ('2d7723d1-f649-4671-90cf-99b576f86a79', 'd6dda401-bd65-4e71-ba47-eb06c9d88046', 'A', 'Promover en la audiencia la idea de que es más ventajoso seguir el camino de la injusticia. El caso de Giges muestra cómo obtuvo beneficios gracias al comportamiento injusto que le posibilitó el anillo.', NULL, FALSE, '2026-11-10 13:38:28+00');
