INSERT INTO "question_options" ("id", "question_id", "option_letter", "option_text", "option_image_path", "is_correct", "created_at") VALUES ('5aa4c46e-151a-480a-a69e-a8a243e1052a', 'd6dda401-bd65-4e71-ba47-eb06c9d88046', 'D', 'Persuadir a la audiencia de que actuar justamente requiere mucha fuerza de voluntad. En el caso de Giges, la tentación derivada del poder del anillo doblegó su voluntad.', NULL, FALSE, '2026-11-10 13:38:29+00');
