INSERT INTO "question_options" ("id", "question_id", "option_letter", "option_text", "option_image_path", "is_correct", "created_at") VALUES ('93da8812-420b-475d-b2a0-d3431ee61940', '0f187b0f-6c55-47f6-b3d5-eb02776a1c88', 'A', 'Porque las 16 personas se encuentran actualmente en la piscina menos profunda. El director de la escuela debe aceptar otros 16 alumnos con una estatura superior a 1,80 m.', NULL, FALSE, '2026-11-11 12:47:49+00');
INSERT INTO "question_options" ("id", "question_id", "option_letter", "option_text", "option_image_path", "is_correct", "created_at") VALUES ('724d7d73-669f-4312-b12d-21dff9874e71', '0f187b0f-6c55-47f6-b3d5-eb02776a1c88', 'B', 'Porque con el promedio es imposible determinar la cantidad de personas en las piscinas. Es necesario utilizar otras medidas, como la estatura máxima o mínima de las personas, en lugar de esta.', NULL, FALSE, '2026-11-11 12:47:50+00');
INSERT INTO "question_options" ("id", "question_id", "option_letter", "option_text", "option_image_path", "is_correct", "created_at") VALUES ('c73adbd5-3faa-4138-a508-44dee46bc50a', '0f187b0f-6c55-47f6-b3d5-eb02776a1c88', 'C', 'Porque incrementar el promedio a 1,80 m es insuficiente. El director de la escuela debe aceptar más estudiantes con una altura de 1,80 m hasta que la cantidad de alumnos sea igual en ambas piscinas.', NULL, FALSE, '2026-11-11 12:47:50+00');
INSERT INTO "question_options" ("id", "question_id", "option_letter", "option_text", "option_image_path", "is_correct", "created_at") VALUES ('ff50e2ea-4716-4a4f-bc14-56f5482a3358', '0f187b0f-6c55-47f6-b3d5-eb02776a1c88', 'D', 'Porque aunque el promedio de estatura de las 16 personas sea inferior a 1,80 m, no significa que la cantidad de personas en las piscinas sea diferente.', NULL, TRUE, '2026-11-11 12:47:50+00');
