INSERT INTO "question_options" ("id", "question_id", "option_letter", "option_text", "option_image_path", "is_correct", "created_at") VALUES ('bb5c5172-7529-4f96-9231-c5bfe773ee3f', '1dec4ea2-1d51-4a98-af5c-83951357d2e2', 'A', 'x = (2 sen(30°)) / sen(45°)', NULL, FALSE, '2026-11-11 12:47:53+00');
INSERT INTO "question_options" ("id", "question_id", "option_letter", "option_text", "option_image_path", "is_correct", "created_at") VALUES ('a93386ee-8c4e-4f8c-990a-53adfeba155c', '1dec4ea2-1d51-4a98-af5c-83951357d2e2', 'B', 'x = (2 sen(60°)) / sen(45°)', NULL, FALSE, '2026-11-11 12:47:53+00');
INSERT INTO "question_options" ("id", "question_id", "option_letter", "option_text", "option_image_path", "is_correct", "created_at") VALUES ('2ab9df1c-8ed0-4746-823d-f5b5561fbce7', '1dec4ea2-1d51-4a98-af5c-83951357d2e2', 'C', 'x = sen(60°) / sen(75°)', NULL, TRUE, '2026-11-11 12:47:54+00');
INSERT INTO "question_options" ("id", "question_id", "option_letter", "option_text", "option_image_path", "is_correct", "created_at") VALUES ('f20c19f6-79f6-4d58-9984-37e706bd6f5f', '1dec4ea2-1d51-4a98-af5c-83951357d2e2', 'D', 'x = sen(30°) / sen(60°)', NULL, FALSE, '2026-11-11 12:47:54+00');
INSERT INTO "question_options" ("id", "question_id", "option_letter", "option_text", "option_image_path", "is_correct", "created_at") VALUES ('74bfcc08-e4e5-448f-b70e-29839e7650b2', 'b27b6757-32d9-4a70-88d4-303650d988cb', 'A', '(3/2)x = 0. Donde x es la cantidad de puntos que anotará P.', NULL, FALSE, '2026-11-11 12:47:55+00');
INSERT INTO "question_options" ("id", "question_id", "option_letter", "option_text", "option_image_path", "is_correct", "created_at") VALUES ('21bfd043-ffb3-4adb-a0d6-9e706503e6f8', 'b27b6757-32d9-4a70-88d4-303650d988cb', 'B', '7 + x = (3/2)x + 2. Donde x es la cantidad de puntos que anotará P.', NULL, TRUE, '2026-11-11 12:47:55+00');
INSERT INTO "question_options" ("id", "question_id", "option_letter", "option_text", "option_image_path", "is_correct", "created_at") VALUES ('48148d8c-a7a3-46c7-9580-482c78a86d17', 'b27b6757-32d9-4a70-88d4-303650d988cb', 'C', '7 + 3x = 2 + 2y. Donde x es la cantidad de puntos que anotará P, y y es la cantidad de puntos que anotará Q.', NULL, FALSE, '2026-11-11 12:47:56+00');
INSERT INTO "question_options" ("id", "question_id", "option_letter", "option_text", "option_image_path", "is_correct", "created_at") VALUES ('5faedf41-0f07-4092-9bcb-5eca66016315', 'b27b6757-32d9-4a70-88d4-303650d988cb', 'D', 'x + y = 7 + 2. Donde x es la cantidad de puntos que anotará P, y y es la cantidad de puntos que anotará Q.', NULL, FALSE, '2026-11-11 12:47:56+00');
INSERT INTO "question_options" ("id", "question_id", "option_letter", "option_text", "option_image_path", "is_correct", "created_at") VALUES ('3541bec3-64a4-4d40-8ffb-bd471e76c38c', 'b1e8ff65-1b21-45f4-9238-6df86b351a6f', 'A', 'G(p) = 30p + 2.000', NULL, TRUE, '2026-11-11 12:47:57+00');
