INSERT INTO "question_options" ("id", "question_id", "option_letter", "option_text", "option_image_path", "is_correct", "created_at") VALUES ('f96ef0fd-25df-4657-b83d-a145c6d65605', '91596490-c889-49c7-af34-380766bf6d74', 'A', 'No, porque aunque la ecuación 1 relaciona cada precio con la variable adecuada de forma correcta, la ecuación 2 significa que se venden 3 veces más mesas que sillas.', NULL, TRUE, '2026-11-11 12:47:59+00');
INSERT INTO "question_options" ("id", "question_id", "option_letter", "option_text", "option_image_path", "is_correct", "created_at") VALUES ('a105467f-6d1d-4f37-be98-5ef657a1d8dc', '91596490-c889-49c7-af34-380766bf6d74', 'B', 'Sí, porque la ecuación 1 relaciona cada precio con la variable adecuada y la ecuación 2 tiene en cuenta que la cantidad de sillas es 3 veces mayor que la de mesas.', NULL, FALSE, '2026-11-11 12:47:59+00');
INSERT INTO "question_options" ("id", "question_id", "option_letter", "option_text", "option_image_path", "is_correct", "created_at") VALUES ('dc3fe7a4-0cff-4386-92f2-0fc8ae44b49d', '91596490-c889-49c7-af34-380766bf6d74', 'C', 'No, porque aunque la ecuación 2 tiene en cuenta que la cantidad de sillas es 3 veces mayor que la de mesas, en la ecuación 1 los precios deberían estar dividiendo y no multiplicando.', NULL, FALSE, '2026-11-11 12:48:00+00');
INSERT INTO "question_options" ("id", "question_id", "option_letter", "option_text", "option_image_path", "is_correct", "created_at") VALUES ('adfbba58-d167-4287-b09e-b5d986301266', '91596490-c889-49c7-af34-380766bf6d74', 'D', 'Sí, porque al solucionar las dos ecuaciones se obtiene un número entero, lo cual es consistente con las condiciones iniciales del problema.', NULL, FALSE, '2026-11-11 12:48:00+00');
