INSERT INTO "question_options" ("id", "question_id", "option_letter", "option_text", "option_image_path", "is_correct", "created_at") VALUES ('944aa18c-639d-4132-be18-0dbf568b3aa6', '8db9020e-c8fc-484a-a20d-74ff9d027d57', 'A', 'No, porque la regla no considera aumentos de 20 dB, solamente de 10 dB; no hay consideraciones para aumentos mayores.', NULL, FALSE, '2026-11-11 12:48:23+00');
INSERT INTO "question_options" ("id", "question_id", "option_letter", "option_text", "option_image_path", "is_correct", "created_at") VALUES ('9f0eda98-4020-44b9-bd60-cd8ca09ce6cb', '8db9020e-c8fc-484a-a20d-74ff9d027d57', 'B', 'Sí, porque la regla presentada indica que para aumentar en x unidades el nivel de la medida de intensidad se agrega x a la intensidad.', NULL, FALSE, '2026-11-11 12:48:23+00');
INSERT INTO "question_options" ("id", "question_id", "option_letter", "option_text", "option_image_path", "is_correct", "created_at") VALUES ('f0dfc8ba-94ff-4a09-ac07-01cbf94b4948', '8db9020e-c8fc-484a-a20d-74ff9d027d57', 'C', 'No, porque aumentar 20 dB equivale a aumentar 10 dB dos veces, es decir, multiplicar por 10 la intensidad dos veces; en total, multiplicar por 100.', NULL, TRUE, '2026-11-11 12:48:24+00');
INSERT INTO "question_options" ("id", "question_id", "option_letter", "option_text", "option_image_path", "is_correct", "created_at") VALUES ('2cf245ce-b1c2-4a03-aaac-a9adece638ce', '8db9020e-c8fc-484a-a20d-74ff9d027d57', 'D', 'Sí, porque el resultado de multiplicar dos veces por 10 la intensidad es multiplicarla por 20; así, se ahorra un paso y obtiene el resultado correcto.', NULL, FALSE, '2026-11-11 12:48:24+00');
INSERT INTO "question_options" ("id", "question_id", "option_letter", "option_text", "option_image_path", "is_correct", "created_at") VALUES ('743dbef9-9511-42ab-a1c0-0709946f6bc1', 'fa0125d9-3b0e-437e-9bef-467bb052affd', 'A', 'En el paso 1, porque el precio de venta es el 90 % del precio original, por tanto, debe multiplicarse por 90 y no por 9.', NULL, FALSE, '2026-11-11 12:48:25+00');
INSERT INTO "question_options" ("id", "question_id", "option_letter", "option_text", "option_image_path", "is_correct", "created_at") VALUES ('3f3b21bb-5d3d-4cc2-86ba-86b15382e737', 'fa0125d9-3b0e-437e-9bef-467bb052affd', 'B', 'En el paso 3, porque el precio final es el 90 % del precio de venta, por tanto, debe multiplicarse por 90 y no por 10.', NULL, TRUE, '2026-11-11 12:48:25+00');
INSERT INTO "question_options" ("id", "question_id", "option_letter", "option_text", "option_image_path", "is_correct", "created_at") VALUES ('84934892-2d64-476c-b182-fe4db3ecba0f', 'fa0125d9-3b0e-437e-9bef-467bb052affd', 'C', 'En el paso 2, porque para calcular el precio al aplicar un porcentaje de descuento es necesario dividir entre 100 y no entre 10.', NULL, FALSE, '2026-11-11 12:48:26+00');
INSERT INTO "question_options" ("id", "question_id", "option_letter", "option_text", "option_image_path", "is_correct", "created_at") VALUES ('1fe9c1c8-dbe1-4d68-aae4-1062f0c1733b', 'fa0125d9-3b0e-437e-9bef-467bb052affd', 'D', 'En el paso 4, porque solo es necesario dividir una vez para calcular el precio final; es suficiente con la división del paso 2.', NULL, FALSE, '2026-11-11 12:48:26+00');
